const paths={grid:'M3 3h5v5H3zM12 3h5v5h-5zM3 12h5v5H3zM12 12h5v5h-5z',menu:'M3 5h14M3 10h14M3 15h14',building:'M4 18V3h9v15M13 8h4v10M2 18h17M7 6h3M7 9h3M7 12h3M7 15h3',people:'M13 17v-2a4 4 0 0 0-8 0v2M9 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6M15 4a3 3 0 0 1 0 6M15 12a4 4 0 0 1 3 4',segment:'M4 4h12v4H4zM2 13h6v4H2zM12 13h6v4h-6zM10 8v3M5 13v-2h10v2',mail:'M2 4h16v12H2zM2 5l8 6 8-6',sync:'M16 7a6 6 0 0 0-10-3L3 7m0-4v4h4M4 13a6 6 0 0 0 10 3l3-3m0 4v-4h-4',search:'M14 14l4 4M9 15A6 6 0 1 0 9 3a6 6 0 0 0 0 12',plus:'M10 3v14M3 10h14',chevron:'M6 8l4 4 4-4',right:'M8 5l5 5-5 5',left:'M12 5l-5 5 5 5',filter:'M2 4h16l-6 7v5l-4 2v-7z',export:'M10 2v11M6 9l4 4 4-4M3 13v5h14v-5',settings:'M8 3l1-1h2l1 3 3-1 2 3-2 2 2 2-2 4-3-1-1 3H9l-1-3-3 1-2-3 2-3-2-2 2-3 3 1zM13 10a3 3 0 1 0-6 0 3 3 0 0 0 6 0',help:'M8 7a2.5 2.5 0 1 1 4 2c-2 1-2 2-2 3M10 15h.01M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',check:'M4 10l4 4 8-8',circlecheck:'M6 10l3 3 5-6M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',clock:'M10 5v5l3 2M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',close:'M5 5l10 10M15 5L5 15',delete:'M3 5h14M7 5V2h6v3M5 5l1 13h8l1-13M8 8v7M12 8v7',edit:'M12 4l4 4M3 17l4-1L17 6a2 2 0 0 0-3-3L4 13z',info:'M10 9v6M10 5h.01M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',save:'M3 2h12l3 3v13H2V2zM6 2v5h8V2M6 18v-7h8v7',more:'M4 10h.01M10 10h.01M16 10h.01',external:'M11 2h7v7M18 2l-9 9M8 3H3v14h14v-5',error:'M10 5v6M10 14h.01M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',home:'M2 9l8-7 8 7M4 8v10h12V8M8 18v-6h4v6',document:'M4 2h8l4 4v12H4zM12 2v5h4M7 10h6M7 13h6'};
const icon=(n,cls='')=>`<svg class="${cls}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.document}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Ąžuolyno klinika','Baltijos sveikata','Santaros odontologija','Neries medicinos centras','Pajūrio šeimos klinika','Žalioji vaistinė','Šilo diagnostika','Saulės reabilitacija','Kopų odontologija','Vingio sveikatos centras','Nemuno klinika','Rytmečio laboratorija','Sveikatos erdvė','Miško šeimos klinika','Liepų medicinos centras','Ąžuolo vaistinė','Smilties klinika','Versmės diagnostika'];
const cities=['Vilnius','Klaipėda','Kaunas','Vilnius','Klaipėda','Šiauliai','Kaunas','Panevėžys','Klaipėda','Vilnius','Kaunas','Šiauliai','Vilnius','Panevėžys','Kaunas','Klaipėda','Vilnius','Šiauliai'];
const sectors=['Klinika','Klinika','Odontologija','Klinika','Klinika','Vaistinė','Diagnostika','Reabilitacija','Odontologija','Klinika','Klinika','Diagnostika','Klinika','Klinika','Klinika','Vaistinė','Klinika','Diagnostika'];
const personNames=['Austėja Žukaitė','Mantas Vaitkus','Ieva Petraitytė','Tomas Rimkus','Rūta Jankutė','Lukas Kazlauskas','Gabija Stankevičė','Paulius Žilinskas','Monika Dapkutė','Dovydas Jonaitis','Eglė Beržinė','Karolis Skučas','Viktorija Gailė','Andrius Petraitis','Diana Mikutė','Simonas Butkus','Justė Palionė','Mindaugas Varnas','Agnė Norkutė','Laura Daukšaitė','Marius Naujokas','Greta Žalytė','Simona Balčiūnė','Darius Gudaitis'];
const ascii=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ž/g,'z').replace(/Ž/g,'Z').replace(/ė/g,'e').toLowerCase();
function seed(){return {clients:names.map((n,i)=>({id:'c'+(i+1),name:'UAB „'+n+'“',code:String(305100201+i*137),city:cities[i],sector:sectors[i],address:['Parko g. 12','Taikos pr. 45','Liepų g. 8'][i%3],phone:'+370 600 '+String(10001+i),email:`info@imone${i+1}.example`,status:i===14||i===17?'Neaktyvus':'Aktyvus',sync:i===4?'Laukiama':i===11?'Klaida':'Sinchronizuota',notes:'Pavyzdinis kliento įrašas demonstracijai.',updated:'2026-11-24T07:00:00'})),contacts:personNames.map((n,i)=>({id:'p'+(i+1),name:n,clientId:'c'+(i%18+1),email:ascii(n).replace(' ','.')+'@pastas.example',phone:'+370 611 '+String(20001+i),position:['Administratorė','Pirkimų vadovas','Klinikos vadovė','Direktorius'][i%4],consent:![3,8,13,20].includes(i),mailStatus:i===8||i===20?'Atsisakė':i===13?'Neprenumeruoja':'Prenumeruoja',sync:i===4?'Laukiama':'Sinchronizuota'})),segments:[{id:'s1',name:'Klinikos · visa Lietuva',desc:'Aktyvių klinikų kontaktai, sutikę gauti naujienlaiškius.',city:'',sector:'Klinika',status:'Aktyvus',consent:true},{id:'s2',name:'Pajūrio klientai',desc:'Klaipėdos klientų kontaktai rinkodaros komunikacijai.',city:'Klaipėda',sector:'',status:'Aktyvus',consent:true},{id:'s3',name:'Visi prenumeratoriai',desc:'Visų aktyvių klientų naujienlaiškių prenumeratoriai.',city:'',sector:'',status:'Aktyvus',consent:true}],campaigns:[{id:'n1',name:'Lapkričio naujienos',subject:'Lapkričio naujienos jūsų komandai',segmentId:'s3',template:'t1',status:'Inicijuota (demo)',count:16,date:'2026-11-23T10:30:00'}],logs:[{id:'l1',date:'2026-11-24T07:00:00',system:'RIVILĖ',direction:'RIVILĖ ↔ Mini CRM',details:'Atnaujinti 16 klientų ir 24 kontaktai.',status:'Sėkminga'},{id:'l2',date:'2026-11-24T07:00:03',system:'RIVILĖ',direction:'Mini CRM → RIVILĖ',details:'Rytmečio laboratorija: trūksta gavėjo lauko susiejimo.',status:'Klaida'},{id:'l3',date:'2026-11-24T07:10:00',system:'Mailchimp',direction:'Mailchimp → Mini CRM',details:'Gauti 3 šablonai, atnaujintos 2 prenumeratos būsenos.',status:'Sėkminga'}],lastRivile:'2026-11-24T07:00:00',lastMail:'2026-11-24T07:10:00'};}
let db;try{db=JSON.parse(localStorage.getItem('miniCRM-v1'));}catch{}if(!db||!Array.isArray(db.clients))db=seed();
const persist=()=>localStorage.setItem('miniCRM-v1',JSON.stringify(db));
let state={page:'clients',search:'',view:'all',city:'',sector:'',filters:false,selected:new Set(),sort:'name',asc:true,pageIndex:0};
let wizard=null;let drawerContext=null;let toastTimer;
const templates=[{id:'t1',name:'Mėnesio naujienos',desc:'Įmonės naujienos ir aktualijos',eyebrow:'NAUJIENLAIŠKIS',title:'Naujienos jūsų komandai',text:'Dalijamės naujausiomis aktualijomis, paslaugų naujienomis ir naudinga informacija jūsų komandai.',color:''},{id:'t2',name:'Paslaugų pristatymas',desc:'Paslaugos ir specialūs pasiūlymai',eyebrow:'PASLAUGŲ NAUJIENOS',title:'Atraskite naujas galimybes',text:'Susipažinkite su mūsų paslaugų naujienomis. Susisiekite su savo vadybininku ir aptarkime jūsų poreikius.',color:'blue'},{id:'t3',name:'Kvietimas į renginį',desc:'Renginiai ir susitikimai',eyebrow:'KVIEČIAME DALYVAUTI',title:'Susitikime gyvai',text:'Kviečiame į susitikimą, kuriame pasidalinsime patirtimi ir aptarsime jūsų organizacijai aktualias temas.',color:'pink'}];
const client=id=>db.clients.find(x=>x.id===id);
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const fmt=d=>new Intl.DateTimeFormat('lt-LT',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Vilnius'}).format(new Date(d));
const plural=(n,one,many,other)=>n%100>=11&&n%100<=19?other:n%10===1?one:n%10>=2&&n%10<=9?many:other;
const uid=p=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,5);
function toast(t){let e=document.getElementById('toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),4000);}
const badge=(s)=>`<span class="badge ${/Neaktyvus|Neprenumeruoja|Juodraštis/.test(s)?'gray':/Klaida|Atsisakė/.test(s)?'red':/Inicijuota/.test(s)?'purple':''}">${esc(s)}</span>`;
const syncBadge=s=>`<span class="sync ${s==='Laukiama'?'pending':s==='Klaida'?'failed':''}">${icon(s==='Laukiama'?'clock':s==='Klaida'?'error':'circlecheck')}${esc(s)}</span>`;
const button=(label,action,ico='',type='')=>`<button class="button ${type}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
function metric(label,value,sub,ico){return `<div class="metric"><div><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-sub">${sub}</div></div><div class="metric-icon">${icon(ico)}</div></div>`;}
function eligible(s){return db.contacts.filter(p=>{let c=client(p.clientId);return c&&(!s.city||c.city===s.city)&&(!s.sector||c.sector===s.sector)&&(!s.status||c.status===s.status)&&(!s.consent||p.consent);});}
function recipients(s){return eligible(s).filter(p=>p.consent&&p.mailStatus==='Prenumeruoja'&&client(p.clientId)?.status==='Aktyvus');}
function nav(page){closeOverlay();state={...state,page,search:'',view:'all',city:'',sector:'',selected:new Set(),pageIndex:0};render();}
function render(){const navs=[['clients','building','Klientai',db.clients.length],['contacts','people','Kontaktai',db.contacts.length],['segments','segment','Segmentai',db.segments.length],['campaigns','mail','Naujienlaiškiai','']];
document.getElementById('app').innerHTML=`<header class="topbar"><button class="mobile-nav" data-action="toggle-nav" aria-label="Atverti navigaciją">${icon('menu')}</button><div class="waffle" aria-hidden="true">${'<i></i>'.repeat(9)}</div><span class="top-brand">Power Apps</span><span class="app-title">Mini CRM</span><label class="global-search">${icon('search')}<input id="globalSearch" placeholder="Ieškoti klientų ir kontaktų" aria-label="Visuotinė paieška"></label><div class="top-right"><button data-action="settings" title="Parametrai" aria-label="Parametrai">${icon('settings')}</button><button data-action="help" title="Pagalba" aria-label="Pagalba">${icon('help')}</button><span class="avatar" title="Demo naudotojas">DN</span></div></header><aside class="sidebar"><button class="side-menu" data-action="toggle-nav" aria-label="Navigacija">${icon('menu')}</button><div class="workspace-label"><span class="workspace-logo">${icon('building')}</span>Klientų valdymas</div><div class="nav-label">Darbo sritis</div>${navs.map(([p,i,n,c])=>`<button class="nav-item ${state.page===p?'active':''}" data-nav="${p}">${icon(i)}${n}<span class="nav-count">${c}</span></button>`).join('')}<div class="nav-label">Duomenų valdymas</div><button class="nav-item ${state.page==='integrations'?'active':''}" data-nav="integrations">${icon('sync')}Integracijos</button><div class="side-bottom"><b>Mini CRM · Demonstracinė aplinka</b><span>Model-driven Power Apps</span><span>Microsoft Dataverse</span></div></aside><main class="main"><div class="commandbar">${commands()}<span class="demo-badge">DEMO · Integracijos imituojamos</span></div><div class="content"><div class="breadcrumb">Klientų valdymas ${icon('right')} ${esc({clients:'Klientai',contacts:'Kontaktai',segments:'Segmentai',campaigns:'Naujienlaiškiai',integrations:'Integracijos'}[state.page])}</div><div id="pageContent">${pageContent()}</div><p class="small-note">${icon('info')}Pavyzdiniai duomenys. Pakeitimai saugomi šioje naršyklėje.</p></div></main>`;bindTable();}
function commands(){let p=state.page;if(p==='clients'||p==='contacts')return `<button class="cmd primary-cmd" data-action="new">${icon('plus')}Naujas ${p==='clients'?'klientas':'kontaktas'}</button><span class="separator"></span><button class="cmd" data-action="refresh">${icon('sync')}<span class="optional">Atnaujinti</span></button><button class="cmd" data-action="export">${icon('export')}<span class="optional">Eksportuoti</span></button><button class="cmd" data-action="toggle-filter">${icon('filter')}<span class="optional">Filtrai</span></button>`;if(p==='segments')return `<button class="cmd primary-cmd" data-action="new-segment">${icon('plus')}Naujas segmentas</button><span class="separator"></span><button class="cmd" data-action="new-campaign">${icon('mail')}Kurti naujienlaiškį</button>`;if(p==='campaigns')return `<button class="cmd primary-cmd" data-action="new-campaign">${icon('plus')}Naujas naujienlaiškis</button><span class="separator"></span><button class="cmd" data-action="templates">${icon('document')}Mailchimp šablonai</button>`;return `<button class="cmd primary-cmd" data-action="sync-all">${icon('sync')}Sinchronizuoti duomenis</button><span class="separator"></span><button class="cmd" data-action="refresh">${icon('sync')}Atnaujinti</button>`;}
function pageHead(title,desc,extra=''){return `<div class="page-head"><div><div class="view-name"><h1>${title}</h1></div><p>${desc}</p></div><div class="head-actions">${extra}</div></div>`;}
function pageContent(){switch(state.page){case'clients':case'contacts':return recordsPage();case'segments':return segmentsPage();case'campaigns':return campaignsPage();case'integrations':return integrationsPage();}}
function recordsPage(){let cp=state.page==='clients';return pageHead(cp?'Klientai':'Kontaktai',cp?'Visi jūsų klientai. Viena vieta ryšiams kurti.':'Kontaktiniai asmenys, jų duomenys ir prenumeratos.',`<span class="sync">${icon('circlecheck')}Paskutinė sinchronizacija ${fmt(db.lastRivile)}</span>`)+`<div class="metrics">${cp?metric('Visi klientai',db.clients.length,'Centralizuota duomenų bazė','building')+metric('Aktyvūs klientai',db.clients.filter(c=>c.status==='Aktyvus').length,'Paruošti darbui','circlecheck')+metric('Kontaktiniai asmenys',db.contacts.length,'Susieti su klientais','people')+metric('Naujienlaiškių prenumeratoriai',db.contacts.filter(c=>c.consent&&c.mailStatus==='Prenumeruoja').length,'Sutikę gauti pranešimus','mail'):metric('Visi kontaktai',db.contacts.length,'Centralizuoti kontaktai','people')+metric('Prenumeratoriai',db.contacts.filter(c=>c.mailStatus==='Prenumeruoja'&&c.consent).length,'Gali gauti naujienlaiškius','mail')+metric('Atsisakę prenumeratos',db.contacts.filter(c=>c.mailStatus==='Atsisakė').length,'Būsena iš Mailchimp','info')+metric('Klientai',db.clients.length,'Susietos organizacijos','building')}</div><div class="table-card"><div class="table-tools"><div class="table-tools-left"><select id="viewSelect" class="view-select" aria-label="Įrašų rodinys">${(cp?[['all','Visi klientai'],['active','Aktyvūs klientai'],['inactive','Neaktyvūs klientai'],['pending','Laukiantys sinchronizavimo']]:[['all','Visi kontaktai'],['subscribed','Naujienlaiškių prenumeratoriai'],['unsubscribed','Atsisakę prenumeratos']]).map(([v,l])=>`<option value="${v}" ${state.view===v?'selected':''}>${l}</option>`).join('')}</select><span class="results-count" id="recordCount"></span></div><div class="tool-right"><label class="search-box">${icon('search')}<input id="recordSearch" placeholder="Ieškoti šiame rodinyje" value="${esc(state.search)}" aria-label="Ieškoti šiame rodinyje"></label><button class="button" data-action="toggle-filter">${icon('filter')}Filtrai</button></div></div>${state.filters?filterBar():''}<div id="selectionBar"></div><div class="table-wrap"><table><thead>${tableHead(cp)}</thead><tbody id="recordRows"></tbody></table></div><div class="table-footer"><span id="rangeCount"></span><span class="technical">Šaltinis: Microsoft Dataverse</span><div class="pagination"><button data-action="prev" aria-label="Ankstesnis puslapis">${icon('left')}</button><span id="pageNumber"></span><button data-action="next" aria-label="Kitas puslapis">${icon('right')}</button></div></div></div>`;}
function filterBar(){return `<div class="filter-bar">${icon('filter')}<label>Miestas <select id="filterCity"><option value="">Visi miestai</option>${[...new Set(db.clients.map(c=>c.city))].sort().map(c=>`<option ${c===state.city?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Veikla <select id="filterSector"><option value="">Visos veiklos</option>${[...new Set(db.clients.map(c=>c.sector))].sort().map(c=>`<option ${c===state.sector?'selected':''}>${esc(c)}</option>`).join('')}</select></label><button class="cmd" data-action="clear-filters">Išvalyti</button><button class="cmd" data-action="segment-from-filter">${icon('segment')}Išsaugoti segmentą</button></div>`;}
function tableHead(cp){let cols=cp?[['name','Kliento pavadinimas'],['code','Įmonės kodas'],['city','Miestas'],['sector','Veikla'],['contact','Pagrindinis kontaktas'],['status','Būsena'],['sync','RIVILĖ']]:[['name','Vardas, pavardė'],['client','Klientas'],['email','El. paštas'],['position','Pareigos'],['mailStatus','Mailchimp būsena'],['consent','Sutikimas']];return `<tr><th class="check-col"><input type="checkbox" id="selectAll" aria-label="Pažymėti puslapio įrašus"></th>${cols.map(([k,n])=>`<th class="sortable" data-sort="${k}">${n} ${state.sort===k?(state.asc?'↑':'↓'):''}</th>`).join('')}<th></th></tr>`;}
function filteredRecords(){let cp=state.page==='clients';return [...(cp?db.clients:db.contacts)].filter(r=>{let c=cp?r:client(r.clientId);if(!c)return false;let text=Object.values(r).join(' ')+' '+c.name+' '+c.city+' '+c.sector;if(!ascii(text).includes(ascii(state.search)))return false;if(state.city&&c.city!==state.city)return false;if(state.sector&&c.sector!==state.sector)return false;let v=state.view;return v==='all'||(v==='active'&&c.status==='Aktyvus')||(v==='inactive'&&c.status==='Neaktyvus')||(v==='pending'&&c.sync!=='Sinchronizuota')||(v==='subscribed'&&r.consent&&r.mailStatus==='Prenumeruoja')||(v==='unsubscribed'&&r.mailStatus==='Atsisakė');}).sort((a,b)=>{let get=r=>state.sort==='client'?client(r.clientId)?.name:state.sort==='contact'?db.contacts.find(p=>p.clientId===r.id)?.name:r[state.sort];return String(get(a)??'').localeCompare(String(get(b)??''),'lt')*(state.asc?1:-1);});}
function updateTable(){if(!['clients','contacts'].includes(state.page))return;let cp=state.page==='clients',all=filteredRecords();let max=Math.max(0,Math.ceil(all.length/10)-1);state.pageIndex=Math.min(state.pageIndex,max);let rows=all.slice(state.pageIndex*10,state.pageIndex*10+10);document.getElementById('recordCount').textContent=all.length+' '+plural(all.length,'įrašas','įrašai','įrašų');document.getElementById('recordRows').innerHTML=rows.length?rows.map(r=>{let p=cp?db.contacts.find(x=>x.clientId===r.id):null;return `<tr class="${state.selected.has(r.id)?'selected':''}"><td class="check-col"><input type="checkbox" data-select="${r.id}" ${state.selected.has(r.id)?'checked':''} aria-label="Pažymėti ${esc(r.name)}"></td><td><button class="entity-name" data-open="${r.id}">${cp?`<span class="entity-icon">${icon('building')}</span>`:`<span class="contact-avatar">${initials(r.name)}</span>`}<span class="name-text">${esc(r.name)}</span></button></td>${cp?`<td class="muted">${esc(r.code)}</td><td>${esc(r.city)}</td><td>${esc(r.sector)}</td><td>${esc(p?.name||'—')}</td><td>${badge(r.status)}</td><td>${syncBadge(r.sync)}</td>`:`<td><button class="cmd" data-client-open="${r.clientId}" style="color:#115ea3;padding:0">${esc(client(r.clientId)?.name)}</button></td><td><a href="mailto:${esc(r.email)}">${esc(r.email)}</a></td><td>${esc(r.position)}</td><td>${badge(r.mailStatus)}</td><td>${r.consent?'<span class="sync">'+icon('check')+'Gautas</span>':'<span class="muted">Negautas</span>'}</td>`}<td class="row-actions"><button data-open="${r.id}" title="Redaguoti įrašą" aria-label="Redaguoti ${esc(r.name)}">${icon('edit')}</button></td></tr>`;}).join(''):`<tr><td colspan="9"><div class="empty">${icon('search')}<h3>Įrašų nerasta</h3><p>Pakeiskite paieškos tekstą arba išvalykite filtrus.</p><button class="button" data-action="clear-filters">Išvalyti filtrus</button></div></td></tr>`;document.getElementById('rangeCount').textContent=all.length?`${state.pageIndex*10+1}–${Math.min(state.pageIndex*10+10,all.length)} iš ${all.length} įrašų`:'0 įrašų';document.getElementById('pageNumber').textContent=`${state.pageIndex+1} / ${max+1}`;document.getElementById('selectAll').checked=rows.length>0&&rows.every(r=>state.selected.has(r.id));document.getElementById('selectionBar').innerHTML=state.selected.size?`<div class="selection-bar"><b>Pažymėta: ${state.selected.size}</b><button class="cmd" data-action="delete-selected">${icon('delete')}Šalinti</button>${cp?'<button class="cmd" data-action="deactivate">Pakeisti aktyvumą</button>':''}<button class="cmd" data-action="clear-selection">Atšaukti žymėjimą</button></div>`:'';}
function bindTable(){if(!['clients','contacts'].includes(state.page))return;updateTable();document.getElementById('recordSearch').addEventListener('input',e=>{state.search=e.target.value;state.pageIndex=0;updateTable();});document.getElementById('viewSelect').addEventListener('change',e=>{state.view=e.target.value;state.pageIndex=0;state.selected.clear();updateTable();});['filterCity','filterSector'].forEach((id,i)=>document.getElementById(id)?.addEventListener('change',e=>{state[i?'sector':'city']=e.target.value;state.pageIndex=0;state.selected.clear();updateTable();}));document.getElementById('selectAll').addEventListener('change',e=>{filteredRecords().slice(state.pageIndex*10,state.pageIndex*10+10).forEach(r=>e.target.checked?state.selected.add(r.id):state.selected.delete(r.id));updateTable();});}
function segmentsPage(){return pageHead('Segmentai','Grupuokite kontaktus ir pasiekite tinkamą auditoriją.',button('Naujas segmentas','new-segment','plus','primary'))+`<div class="status-banner">${icon('info')}Segmentai atnaujinami pagal klientų ir kontaktų duomenis. Naujienlaiškiams atrenkami tik aktyvių klientų kontaktai su galiojančia prenumerata ir sutikimu.</div><div class="segment-grid">${db.segments.map(s=>`<article class="segment-card"><div class="segment-top"><div class="metric-icon">${icon('segment')}</div><h3>${esc(s.name)}</h3><button class="icon-button" data-segment-edit="${s.id}" title="Redaguoti segmentą" style="margin-left:auto">${icon('edit')}</button></div><p>${esc(s.desc||'Kontaktai atrenkami pagal nurodytas taisykles.')}</p><div class="chips">${[s.city||'Visi miestai',s.sector||'Visos veiklos',s.status||'Visos būsenos',s.consent?'Su sutikimu':'Visi sutikimai'].map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="segment-bottom"><div class="count-large">${recipients(s).length}<small>${plural(recipients(s).length,'gavėjas','gavėjai','gavėjų')}</small></div><button class="cmd" data-segment-view="${s.id}">Peržiūrėti ${icon('right')}</button></div><button class="button primary" data-segment-send="${s.id}" style="margin-top:16px;width:100%">${icon('mail')}Kurti naujienlaiškį</button></article>`).join('')}</div>`;}
function campaignsPage(){return pageHead('Naujienlaiškiai','Pasirinkite segmentą ir „Mailchimp“ šabloną. Inicijuokite siuntimą.',button('Naujas naujienlaiškis','new-campaign','plus','primary'))+`<div class="metrics">${metric('Inicijuoti naujienlaiškiai',db.campaigns.filter(c=>c.status!=='Juodraštis').length,'Demonstracinis siuntimas','mail')+metric('Juodraščiai',db.campaigns.filter(c=>c.status==='Juodraštis').length,'Laukia peržiūros','edit')+metric('Mailchimp šablonai',templates.length,'Sinchronizuoti šablonai','document')+metric('Kontaktų segmentai',db.segments.length,'Dinaminės auditorijos','segment')}</div><div class="table-card"><div class="table-tools"><h3>Visi naujienlaiškiai</h3><span class="results-count">${db.campaigns.length} ${plural(db.campaigns.length,'įrašas','įrašai','įrašų')}</span></div><div class="table-wrap"><table><thead><tr><th>Pavadinimas</th><th>Segmentas</th><th>Šablonas</th><th>Gavėjai</th><th>Būsena</th><th>Data</th></tr></thead><tbody>${db.campaigns.map(c=>`<tr><td><button class="entity-name" data-campaign-open="${c.id}">${icon('mail')} ${esc(c.name)}</button></td><td>${esc(db.segments.find(s=>s.id===c.segmentId)?.name||'Pašalintas segmentas')}</td><td>${esc(templates.find(t=>t.id===c.template)?.name||'—')}</td><td>${c.count}</td><td>${badge(c.status)}</td><td class="muted">${fmt(c.date)}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><h3>Naujienlaiškių dar nėra</h3><p>Pradėkite pasirinkdami segmentą ir šabloną.</p></div></td></tr>'}</tbody></table></div><div class="table-footer">Inicijavimas šiame prototipe yra demonstracinis. Laiškai nesiunčiami.</div></div><div class="section-title">Mailchimp šablonai</div><div class="segment-grid">${templates.map(t=>templateTile(t)).join('')}</div>`;}
function templateTile(t,select=false){return `<div class="template ${wizard?.template===t.id&&select?'selected':''}" ${select?`data-template="${t.id}" role="button" tabindex="0" aria-label="Pasirinkti ${esc(t.name)}"`:`data-preview-template="${t.id}" role="button" tabindex="0"`}><div class="template-preview ${t.color}"><span>${t.eyebrow}</span><strong>${t.title}</strong><div class="mini-line"></div><div class="mini-line" style="width:60%"></div><div class="mini-button"></div></div><div class="template-info">${t.name}<small>${t.desc}</small></div></div>`;}
function integrationsPage(){return pageHead('Integracijos','Duomenų apsikeitimas tarp mini CRM, RIVILĖ ir Mailchimp.')+`<div class="status-banner">${icon('info')}Demonstracinė aplinka: jungtys imituojamos, tikros paskyros neprijungtos. Sinchronizavimas atnaujina pavyzdinius įrašus ir operacijų žurnalą.</div><div class="integration-grid">${integrationCard('RIVILĖ','R','Klientai ir kontaktiniai asmenys',db.lastRivile,'1 kartą per parą','Abipusė sinchronizacija','rivile')}${integrationCard('Mailchimp','m','Kontaktai, segmentai ir šablonai',db.lastMail,'Pagal integracijos veiksmą','Abipusis duomenų apsikeitimas','mail')}</div><div class="table-card"><div class="table-tools"><h3>Integracijų žurnalas</h3><span class="results-count">Naujausi veiksmai</span></div><div class="table-wrap"><table><thead><tr><th>Laikas</th><th>Sistema</th><th>Kryptis</th><th>Rezultatas</th><th>Būsena</th></tr></thead><tbody>${[...db.logs].reverse().slice(0,20).map(l=>`<tr><td class="muted">${fmt(l.date)}</td><td>${esc(l.system)}</td><td>${esc(l.direction)}</td><td style="max-width:450px;white-space:normal">${esc(l.details)}</td><td>${badge(l.status)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">RIVILĖ: įrašų atnaujinimo ir šalinimo scenarijai · Mailchimp: prenumeratos ir segmentų požymiai</div></div>`;}
function integrationCard(name,letter,desc,date,schedule,dir,key){return `<div class="panel"><div class="integration-head"><div class="brand-box ${key==='mail'?'yellow':''}">${letter}</div><div><h2>${name}</h2><p>${desc}</p></div><span class="badge purple">Demo jungtis</span></div><div class="detail-row"><span>Duomenų perdavimas</span><b>${dir}</b></div><div class="detail-row"><span>Sinchronizavimo dažnis</span><b>${schedule}</b></div><div class="detail-row"><span>Paskutinis atnaujinimas</span><b>${fmt(date)}</b></div><div class="detail-row"><span>${key==='rivile'?'Laukiantys / su klaida':'Mailchimp šablonai'}</span><b>${key==='rivile'?db.clients.filter(c=>c.sync!=='Sinchronizuota').length:templates.length}</b></div><div class="integration-actions"><span class="technical">${key==='rivile'?'RIVILĖ API':'Mailchimp API'} · demonstracija</span>${button('Sinchronizuoti','sync-'+key,'sync')}</div></div>`;}
function closeOverlay(){document.getElementById('overlay').innerHTML='';drawerContext=null;}
function drawer(title,subtitle,body,foot='',wide=false,tabs=''){document.getElementById('overlay').innerHTML=`<div class="backdrop"><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-header"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close" aria-label="Uždaryti">${icon('close')}</button></div>${tabs}<div class="drawer-body">${body}</div>${foot?`<div class="drawer-footer">${foot}</div>`:''}</section></div>`;setTimeout(()=>document.querySelector('.drawer input:not([type=checkbox]), .drawer select, .drawer button')?.focus(),50);}
function field(name,label,value='',type='text',full=false,required=false){return `<div class="field ${full?'full':''}"><label for="f-${name}" class="${required?'required':''}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`;}
function selectField(name,label,value,options,full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></div>`;}
function openRecord(id=null,type=state.page,tab='general'){let cp=type==='clients',r=id?(cp?db.clients:db.contacts).find(x=>x.id===id):{};if(!r)return;drawerContext={id,type,tab};let tabs=id?`<div class="tabs"><button class="${tab==='general'?'active':''}" data-record-tab="general">Bendra informacija</button><button class="${tab==='related'?'active':''}" data-record-tab="related">${cp?'Kontaktai':'Klientas'}</button><button class="${tab==='sync'?'active':''}" data-record-tab="sync">Integracijos</button></div>`:'';let body='';if(tab==='general'){body=`<form id="recordForm"><div class="section-title">${cp?'Kliento duomenys':'Kontaktinis asmuo'}</div><div class="form-grid">${field('name',cp?'Kliento pavadinimas':'Vardas, pavardė',r.name,'text',true,true)}${cp?field('code','Įmonės kodas',r.code,'text',false,true)+selectField('status','Būsena',r.status||'Aktyvus',['Aktyvus','Neaktyvus'])+selectField('city','Miestas',r.city||'Vilnius',['Vilnius','Kaunas','Klaipėda','Šiauliai','Panevėžys','Kitas'])+selectField('sector','Veikla',r.sector||'Klinika',['Klinika','Odontologija','Vaistinė','Diagnostika','Reabilitacija','Kita'])+field('address','Adresas',r.address,'text',true):selectField('clientId','Klientas',r.clientId||db.clients[0]?.id,db.clients.map(c=>[c.id,c.name]),true)+field('position','Pareigos',r.position,'text',true)}${field('email','El. paštas',r.email,'email',false,true)}${field('phone','Telefonas',r.phone,'tel')}${cp?`<div class="field full"><label for="f-notes">Pastabos</label><textarea id="f-notes" name="notes" rows="3">${esc(r.notes)}</textarea></div>`:`<div class="field full"><label class="inline-check"><input type="checkbox" name="consent" ${r.consent?'checked':''}>Gautas sutikimas gauti naujienlaiškius</label></div>${selectField('mailStatus','Mailchimp prenumerata',r.mailStatus||'Neprenumeruoja',['Prenumeruoja','Neprenumeruoja','Atsisakė'],true)}`}</div><div class="form-note">${icon('info')} ${cp?'Įrašas bus paruoštas kitai RIVILĖ sinchronizacijai.':'Prenumeratos būsena ir sutikimas naudojami naujienlaiškių gavėjų atrankai.'}</div><div id="formError" class="field-error" role="alert"></div></form>`;}else if(tab==='related'){let ps=cp?db.contacts.filter(p=>p.clientId===id):[];body=cp?`<div class="panel-title"><h3>Kliento kontaktai (${ps.length})</h3><button class="button" data-add-contact="${id}">${icon('plus')}Naujas</button></div>${ps.map(p=>`<div class="record-card"><span class="contact-avatar">${initials(p.name)}</span><div style="flex:1"><button class="entity-name" data-contact-open="${p.id}">${esc(p.name)}</button><p>${esc(p.position)} · ${esc(p.email)}</p></div>${badge(p.mailStatus)}</div>`).join('')||'<div class="empty"><p>Kontaktų dar nėra. Pridėkite kontaktinį asmenį.</p></div>'}`:`<div class="record-card"><span class="entity-icon">${icon('building')}</span><div><button class="entity-name" data-client-open="${r.clientId}">${esc(client(r.clientId)?.name)}</button><p>${esc(client(r.clientId)?.city)} · ${esc(client(r.clientId)?.code)}</p></div></div>`;}else body=`<div class="section-title">Įrašo sinchronizavimas</div><div class="detail-row"><span>RIVILĖ būsena</span>${syncBadge(r.sync||'Laukiama')}</div><div class="detail-row"><span>Duomenų kryptis</span><b>Abipusė</b></div><div class="detail-row"><span>Dažnis</span><b>1 kartą per parą</b></div>${!cp?`<div class="detail-row"><span>Mailchimp prenumerata</span>${badge(r.mailStatus)}</div><div class="detail-row"><span>Sutikimas</span><b>${r.consent?'Gautas':'Negautas'}</b></div>`:''}<div class="form-note">Šiame prototipe integracijos imituojamos. Atnaujinti įrašai pažymimi kaip laukiantys sinchronizacijos.</div><button class="button" data-action="sync-record" style="margin-top:20px">${icon('sync')}Sinchronizuoti įrašą</button>`;
drawer(id?esc(r.name):(cp?'Naujas klientas':'Naujas kontaktas'),cp?'Klientas · Microsoft Dataverse':'Kontaktas · Microsoft Dataverse',body,`${id?button('Šalinti','delete-record','delete','danger'):''}${button('Uždaryti','close')}${tab==='general'?'<button class="button primary" type="submit" form="recordForm">'+icon('save')+'Išsaugoti</button>':''}`,false,tabs);drawerContext={id,type,tab};document.getElementById('recordForm')?.addEventListener('submit',e=>{e.preventDefault();saveRecord(e.target,id,type);});}
function saveRecord(form,id,type){let data=Object.fromEntries(new FormData(form)),cp=type==='clients';data.name=data.name.trim();data.email=data.email.trim();let err=document.getElementById('formError');if(!data.name){err.textContent='Įveskite pavadinimą arba vardą ir pavardę.';return;}if(cp){data.code=data.code.trim();if(!/^\d{7,9}$/.test(data.code)){err.textContent='Įmonės kodą turi sudaryti nuo 7 iki 9 skaitmenų.';return;}if(db.clients.some(c=>c.code===data.code&&c.id!==id)){err.textContent='Klientas su tokiu įmonės kodu jau yra.';return;}}else{data.consent=form.elements.consent.checked;if(!data.clientId){err.textContent='Pasirinkite klientą.';return;}if(data.mailStatus==='Prenumeruoja'&&!data.consent){err.textContent='Prenumeratai būtinas sutikimas. Pažymėkite sutikimą arba pakeiskite prenumeratos būseną.';return;}if(db.contacts.some(p=>p.email.toLowerCase()===data.email.toLowerCase()&&p.id!==id)){err.textContent='Kontaktas su tokiu el. pašto adresu jau yra.';return;}}let list=cp?db.clients:db.contacts;let old=list.find(r=>r.id===id);data={...old,...data,id:id||uid(cp?'c':'p'),sync:'Laukiama',updated:new Date().toISOString()};if(old)list[list.indexOf(old)]=data;else list.unshift(data);persist();closeOverlay();render();toast(cp?'Klientas išsaugotas.':'Kontaktas išsaugotas.');}
function openSegment(id=null,fromFilters=false){let s=db.segments.find(x=>x.id===id)||{name:'',desc:'',city:fromFilters?state.city:'',sector:fromFilters?state.sector:'',status:state.view==='inactive'?'Neaktyvus':'Aktyvus',consent:true};drawer(id?'Redaguoti segmentą':'Naujas segmentas','Dinaminė kontaktų atranka',`<form id="segmentForm"><div class="form-grid">${field('name','Segmento pavadinimas',s.name,'text',true,true)}<div class="field full"><label for="f-desc">Aprašymas</label><textarea name="desc" id="f-desc" rows="2">${esc(s.desc)}</textarea></div></div><div class="section-title">Atrankos taisyklės</div><div class="rule-editor"><p class="technical" style="margin-bottom:15px">Turi atitikti visas nurodytas sąlygas (IR).</p><div class="form-grid">${selectField('city','Kliento miestas',s.city,[['','Visi miestai'],...new Set(db.clients.map(c=>c.city))])}${selectField('sector','Kliento veikla',s.sector,[['','Visos veiklos'],...new Set(db.clients.map(c=>c.sector))])}${selectField('status','Kliento būsena',s.status,[['','Visos būsenos'],'Aktyvus','Neaktyvus'],true)}<label class="inline-check field full"><span><input type="checkbox" name="consent" ${s.consent?'checked':''}>Tik kontaktai su sutikimu</span></label></div></div><div id="segmentPreview"></div><div id="formError" class="field-error" role="alert"></div></form>`,`${id?button('Šalinti','delete-segment:'+id,'delete','danger'):''}${button('Atšaukti','close')}<button class="button primary" type="submit" form="segmentForm">${icon('save')}Išsaugoti segmentą</button>`);let f=document.getElementById('segmentForm');const preview=()=>{let d=Object.fromEntries(new FormData(f));d.consent=f.elements.consent.checked;document.getElementById('segmentPreview').innerHTML=`<div class="stat-summary"><strong>${recipients(d).length}</strong><span>tinkami naujienlaiškio gavėjai<br>${eligible(d).length} kontaktai atitinka segmento taisykles</span></div>`;};f.addEventListener('change',preview);preview();f.addEventListener('submit',e=>{e.preventDefault();let d=Object.fromEntries(new FormData(f));d.name=d.name.trim();if(!d.name){document.getElementById('formError').textContent='Įveskite segmento pavadinimą.';return;}d.consent=f.elements.consent.checked;d.id=id||uid('s');if(id)db.segments[db.segments.findIndex(x=>x.id===id)]=d;else db.segments.push(d);persist();closeOverlay();state.page='segments';render();toast('Segmentas išsaugotas.');});}
function viewSegment(id){let s=db.segments.find(x=>x.id===id);let ps=eligible(s),rs=recipients(s);drawer(esc(s.name),'Segmento kontaktai',`<div class="stat-summary"><strong>${rs.length}</strong><span>tinkami gavėjai<br>${ps.length} kontaktai pagal segmento taisykles</span></div><div class="recipient-list">${ps.map(p=>`<div class="recipient-row"><div><b>${esc(p.name)}</b><br><small>${esc(p.email)}</small></div>${rs.some(x=>x.id===p.id)?badge('Prenumeruoja'):badge(p.mailStatus==='Atsisakė'?'Atsisakė':'Neprenumeruoja')}</div>`).join('')||'<div class="empty">Kontaktų nėra.</div>'}</div><p class="form-note">Prieš siuntimą pakartotinai patikrinamas sutikimas, prenumerata ir kliento aktyvumas.</p>`,`${button('Redaguoti','edit-segment:'+id,'edit')}<button class="button primary" data-segment-send="${id}">${icon('mail')}Kurti naujienlaiškį</button>`);}
function startWizard(segmentId='',campaignId=null){let c=db.campaigns.find(c=>c.id===campaignId);wizard=c?{...c,step:1}:{id:null,step:1,segmentId:segmentId||db.segments[0]?.id||'',template:'t1',name:'',subject:''};renderWizard();}
function renderWizard(){let w=wizard,s=db.segments.find(s=>s.id===w.segmentId),rs=s?recipients(s):[];let steps=`<div class="steps">${['Auditorija','Šablonas','Peržiūra'].map((x,i)=>`<div class="step ${w.step>=i+1?'active':''}"><b>${i+1}</b>${x}</div>`).join('')}</div>`;let body;if(w.step===1)body=`${field('campaignName','Vidinis naujienlaiškio pavadinimas',w.name,'text',true,true)}<div style="margin-top:20px">${selectField('campaignSegment','Kontaktų segmentas',w.segmentId,[['','Pasirinkite segmentą'],...db.segments.map(s=>[s.id,s.name])],true)}</div><div class="stat-summary"><strong>${rs.length}</strong><span>gavėjai su galiojančia prenumerata<br>${s?esc(s.name):'Pasirinkite segmentą'}</span></div><div class="recipient-list">${rs.map(p=>`<div class="recipient-row"><div><b>${esc(p.name)}</b><br><small>${esc(client(p.clientId)?.name)}</small></div><small>${esc(p.email)}</small></div>`).join('')||'<div class="empty"><p>Šiame segmente tinkamų gavėjų nėra.</p></div>'}</div><div class="form-note">Atsisakę prenumeratos, nedavę sutikimo ir neaktyvių klientų kontaktai į siuntimą neįtraukiami.</div>`;else if(w.step===2)body=`<h3 style="margin-bottom:15px">Pasirinkite Mailchimp šabloną</h3><div class="template-grid">${templates.map(t=>templateTile(t,true)).join('')}</div><div style="margin-top:23px">${field('campaignSubject','Laiško tema',w.subject,'text',true,true)}</div><p class="form-note">Naudojami iš Mailchimp gautų šablonų pavyzdžiai. Šablonų redagavimas vyksta Mailchimp.</p>`;else body=`<h3>Peržiūrėkite prieš inicijuodami siuntimą</h3><div class="summary-box"><div class="detail-row"><span>Naujienlaiškis</span><b>${esc(w.name)}</b></div><div class="detail-row"><span>Segmentas</span><b>${esc(s?.name)}</b></div><div class="detail-row"><span>Gavėjai</span><b>${rs.length} kontaktai</b></div><div class="detail-row"><span>Siuntimo kanalas</span><b>Mailchimp · demonstracija</b></div></div>${emailPreview(w.template,w.subject)}<div class="form-note">${icon('info')}Patvirtinus bus sukurtas demonstracinis inicijavimo įrašas. Tikri laiškai nesiunčiami.</div>`;
drawer('Naujas naujienlaiškis','Mini CRM → Mailchimp',steps+body+'<div id="wizardError" class="field-error" role="alert"></div>',`${button('Išsaugoti juodraštį','wizard-draft','save')}${w.step>1?button('Atgal','wizard-back'):button('Atšaukti','close')}${button(w.step===3?'Inicijuoti siuntimą':'Toliau',w.step===3?'wizard-confirm':'wizard-next',w.step===3?'mail':'','primary')}`,true);document.getElementById('f-campaignSegment')?.addEventListener('change',e=>{w.name=document.getElementById('f-campaignName').value;w.segmentId=e.target.value;renderWizard();});}
function captureWizard(){let n=document.getElementById('f-campaignName'),s=document.getElementById('f-campaignSubject');if(n)wizard.name=n.value.trim();if(s)wizard.subject=s.value.trim();}
function emailPreview(template,subject='Šablono peržiūra'){let t=templates.find(t=>t.id===template)||templates[0];return `<div class="email-preview"><div class="email-top"><b>Tema:</b> ${esc(subject)}<br><b>Siuntėjas:</b> Jūsų komanda &lt;naujienos@imone.example&gt;</div><div class="email-body"><div class="email-logo">JŪSŲ ORGANIZACIJA</div><h2>${t.title}</h2><p>${t.text}</p><span class="email-cta">Sužinoti daugiau</span></div><div class="email-foot">Šį laišką gaunate, nes esate užsiprenumeravę naujienas.<br>Prenumeratos valdymas · Atsisakyti prenumeratos<br>Demonstracinė šablono peržiūra</div></div>`;}
function saveCampaign(draft){captureWizard();let w=wizard,s=db.segments.find(s=>s.id===w.segmentId),rs=s?recipients(s):[];if(!w.name){document.getElementById('wizardError').textContent='Įveskite naujienlaiškio pavadinimą.';return;}if(!draft&&(!s||!rs.length||!w.subject)){document.getElementById('wizardError').textContent='Patikrinkite segmentą, gavėjus ir laiško temą.';return;}let data={id:w.id||uid('n'),name:w.name,subject:w.subject,segmentId:w.segmentId,template:w.template,status:draft?'Juodraštis':'Inicijuota (demo)',count:rs.length,date:new Date().toISOString()};let idx=db.campaigns.findIndex(c=>c.id===data.id);if(idx<0)db.campaigns.unshift(data);else db.campaigns[idx]=data;if(!draft)db.logs.push({id:uid('l'),date:data.date,system:'Mailchimp',direction:'Mini CRM → Mailchimp',details:`Demo inicijavimas: „${data.name}“, ${rs.length} gavėjai, šablonas „${templates.find(t=>t.id===w.template).name}“.`,status:'Sėkminga'});persist();closeOverlay();state.page='campaigns';render();if(draft)toast('Naujienlaiškio juodraštis išsaugotas.');else drawer('Siuntimas inicijuotas','Demonstracinis Mailchimp veiksmas',`<div class="success-state"><div class="success-icon">${icon('check')}</div><h2>Naujienlaiškis paruoštas</h2><p>„${esc(data.name)}“ inicijuotas segmentui<br><b>${esc(s.name)}</b>.</p><div class="stat-summary" style="justify-content:center"><strong>${rs.length}</strong><span>demonstraciniai gavėjai</span></div><p>Veiksmas užregistruotas integracijų žurnale.<br>Tikri el. laiškai nebuvo siunčiami.</p></div>`,button('Baigti','close','','primary'));}
function viewCampaign(id){let c=db.campaigns.find(c=>c.id===id);if(c.status==='Juodraštis')return startWizard('',id);drawer(esc(c.name),'Naujienlaiškio informacija',`<div class="detail-row"><span>Būsena</span>${badge(c.status)}</div><div class="detail-row"><span>Segmentas</span><b>${esc(db.segments.find(s=>s.id===c.segmentId)?.name||'Pašalintas')}</b></div><div class="detail-row"><span>Gavėjų skaičius inicijuojant</span><b>${c.count}</b></div><div class="detail-row"><span>Data</span><b>${fmt(c.date)}</b></div>${emailPreview(c.template,c.subject)}<div class="form-note">Demonstracinis inicijavimo įrašas. Tai nėra laiškų pristatymo ar atidarymo statistika.</div>`,button('Uždaryti','close'));}
function confirmModal(title,text,callback,cancel=null){document.getElementById('overlay').innerHTML=`<div class="modal-wrap"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2><p>${esc(text)}</p><div class="modal-actions">${button('Atšaukti','close')}<button class="button primary" id="confirmButton">Patvirtinti</button></div></div></div>`;document.getElementById('confirmButton').onclick=()=>{closeOverlay();callback();};if(cancel)document.querySelector('.modal [data-action=close]').onclick=e=>{e.stopPropagation();cancel();};document.querySelector('.modal button')?.focus();}
function deleteRecords(ids,type){let cp=type==='clients',list=cp?db.clients:db.contacts;confirmModal('Šalinti įrašus?',`Bus pašalinta įrašų: ${ids.length}.${cp?' Susiję kontaktai taip pat bus pašalinti.':''} Šalinimas bus pažymėtas demonstraciniame integracijų žurnale.`,()=>{if(cp){db.clients=list.filter(c=>!ids.includes(c.id));db.contacts=db.contacts.filter(p=>!ids.includes(p.clientId));}else db.contacts=list.filter(p=>!ids.includes(p.id));db.logs.push({id:uid('l'),date:new Date().toISOString(),system:'RIVILĖ',direction:'Mini CRM → RIVILĖ',details:`Šalinimo scenarijus (demo): ${ids.length} ${cp?'klientų':'kontaktų'} įrašai.`,status:'Sėkminga'});state.selected.clear();persist();render();toast('Įrašai pašalinti.');});}
function exportRecords(){let cp=state.page==='clients',rows=filteredRecords();let cols=cp?['name','code','city','sector','email','phone','status']:['name','client','email','phone','position','consent','mailStatus'];let labels=cp?['Klientas','Įmonės kodas','Miestas','Veikla','El. paštas','Telefonas','Būsena']:['Kontaktas','Klientas','El. paštas','Telefonas','Pareigos','Sutikimas','Mailchimp būsena'];const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';let csv='\uFEFF'+[labels,...rows.map(r=>cols.map(k=>k==='client'?client(r.clientId)?.name:k==='consent'?(r.consent?'Gautas':'Negautas'):r[k]))].map(r=>r.map(cell).join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=(cp?'Klientai':'Kontaktai')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Eksportuoti šio rodinio įrašai: '+rows.length+'.');}
let syncing=false;
async function runSync(system='all'){if(syncing)return;syncing=true;let target=system==='mail'?'Mailchimp':system==='rivile'?'RIVILĖ':'RIVILĖ ir Mailchimp';drawer('Vyksta sinchronizavimas','Demonstracinis duomenų apsikeitimas',`<div class="success-state">${icon('sync','spinning')}<h2 style="margin-top:20px">${target}</h2><p>Atnaujinami pavyzdiniai klientai, kontaktai ir integracijos būsena.</p><div class="progress-bar"><i></i></div></div>`);await new Promise(r=>setTimeout(r,1100));let now=new Date().toISOString();if(system!=='mail'){db.clients.forEach(c=>c.sync='Sinchronizuota');db.contacts.forEach(c=>c.sync='Sinchronizuota');db.lastRivile=now;db.logs.push({id:uid('l'),date:now,system:'RIVILĖ',direction:'RIVILĖ ↔ Mini CRM',details:`Demo: patikrinta ${db.clients.length} klientų ir ${db.contacts.length} kontaktų. Laukiantys įrašai ir klaidos sutvarkyti.`,status:'Sėkminga'});}if(system!=='rivile'){db.lastMail=now;db.logs.push({id:uid('l'),date:now,system:'Mailchimp',direction:'Mini CRM ↔ Mailchimp',details:`Demo: perduoti ${db.contacts.length} kontaktų duomenys, ${db.segments.length} segmentų požymiai, gauti ${templates.length} šablonai ir prenumeratų būsenos.`,status:'Sėkminga'});}persist();syncing=false;closeOverlay();render();toast(target+': demonstracinė sinchronizacija baigta.');}
function settings(){drawer('Aplikacijos parametrai','Mini CRM · Demonstracinė aplinka',`<div class="section-title">Prieiga</div><p style="font-size:14px;line-height:1.7;color:#605e5c">Pasiūlyme numatyta iki 5 vidinių naudotojų, turinčių vienodą prieigos lygį. Atskiros aplikacijos rolės nenumatytos.</p><div class="user-row"><span class="avatar">DN</span><div><b>Demo naudotojas</b><p>Visos mini CRM funkcijos</p></div><span class="badge purple">Vienoda prieiga</span></div><div class="section-title">Duomenys</div><div class="detail-row"><span>Duomenų šaltinis sprendime</span><b>Microsoft Dataverse</b></div><div class="detail-row"><span>Šio prototipo duomenys</span><b>Ši naršyklė</b></div><div class="form-note">Pradinis Lietuvos įmonių importas pasiūlyme numatytas kaip galimas atskiras etapas ir šiame prototipe neįtrauktas.</div><button class="button danger" style="margin-top:22px" data-action="reset">${icon('sync')}Atkurti pavyzdinius duomenis</button>`,button('Uždaryti','close'));}
function help(){drawer('Kaip išbandyti prototipą','Model-driven Power Apps stiliaus mini CRM',`<ol class="help-list"><li><b>Klientai.</b> Suraskite organizaciją, atverkite įrašą, pakeiskite duomenis ir išsaugokite.</li><li><b>Kontaktai.</b> Pridėkite kontaktą, susiekite su klientu ir nustatykite sutikimą bei prenumeratos būseną.</li><li><b>Segmentai.</b> Atrinkite kontaktus pagal miestą, veiklą, kliento būseną ir sutikimą.</li><li><b>Naujienlaiškiai.</b> Pasirinkite segmentą, Mailchimp šabloną, įrašykite temą ir inicijuokite demonstracinį siuntimą.</li><li><b>Integracijos.</b> Paleiskite imitacinę sinchronizaciją ir peržiūrėkite rezultatą žurnale.</li></ol><div class="form-note">Tai veikiantis naršyklinis prototipas. Power Apps, Dataverse, RIVILĖ ir Mailchimp paskyros neprijungtos. Duomenys saugomi tik šioje naršyklėje.</div>`,button('Pradėti','close','','primary'));}
function action(a){if(a==='close')return closeOverlay();if(a==='toggle-nav')return document.querySelector('.sidebar').classList.toggle('mobile-open');if(a==='new')return openRecord();if(a==='help')return help();if(a==='settings')return settings();if(a==='toggle-filter'){state.filters=!state.filters;return render();}if(a==='clear-filters'){state.search='';state.view='all';state.city='';state.sector='';state.pageIndex=0;state.selected.clear();return render();}if(a==='refresh'){render();return toast('Rodinys atnaujintas iš šios naršyklės duomenų.');}if(a==='next'){state.pageIndex=Math.min(state.pageIndex+1,Math.max(0,Math.ceil(filteredRecords().length/10)-1));return updateTable();}if(a==='prev'){state.pageIndex=Math.max(0,state.pageIndex-1);return updateTable();}if(a==='export')return exportRecords();if(a==='clear-selection'){state.selected.clear();return updateTable();}if(a==='delete-selected')return deleteRecords([...state.selected],state.page);if(a==='deactivate'){db.clients.filter(c=>state.selected.has(c.id)).forEach(c=>{c.status=c.status==='Aktyvus'?'Neaktyvus':'Aktyvus';c.sync='Laukiama';});persist();render();return toast('Pasirinktų klientų aktyvumas pakeistas.');}if(a==='delete-record'){let c={...drawerContext};return deleteRecords([c.id],c.type);}if(a==='sync-record'){let c={...drawerContext},r=(c.type==='clients'?db.clients:db.contacts).find(r=>r.id===c.id);r.sync='Sinchronizuota';db.logs.push({id:uid('l'),date:new Date().toISOString(),system:'RIVILĖ',direction:'Mini CRM ↔ RIVILĖ',details:'Demo: sinchronizuotas įrašas „'+r.name+'“.',status:'Sėkminga'});persist();openRecord(c.id,c.type,'sync');return toast('Įrašo sinchronizacija imituota.');}if(a==='new-segment')return openSegment();if(a==='segment-from-filter')return openSegment(null,true);if(a.startsWith('edit-segment:'))return openSegment(a.split(':')[1]);if(a.startsWith('delete-segment:')){let id=a.split(':')[1];return confirmModal('Šalinti segmentą?','Kontaktai liks duomenų bazėje. Susiję naujienlaiškių įrašai išliks.',()=>{db.segments=db.segments.filter(s=>s.id!==id);persist();render();toast('Segmentas pašalintas.');});}if(a==='new-campaign')return startWizard();if(a==='templates'){drawer('Mailchimp šablonai','Iš Mailchimp gaunami šablonų pavyzdžiai',`<div class="template-grid">${templates.map(t=>templateTile(t)).join('')}</div>`,button('Uždaryti','close'),true);return;}if(a==='wizard-next'){captureWizard();let err=document.getElementById('wizardError');if(wizard.step===1){if(!wizard.name){err.textContent='Įveskite naujienlaiškio pavadinimą.';return;}let s=db.segments.find(s=>s.id===wizard.segmentId);if(!s||!recipients(s).length){err.textContent='Pasirinkite segmentą, kuriame yra tinkamų gavėjų.';return;}}if(wizard.step===2&&!wizard.subject){err.textContent='Įveskite laiško temą.';return;}wizard.step++;return renderWizard();}if(a==='wizard-back'){captureWizard();wizard.step--;return renderWizard();}if(a==='wizard-draft')return saveCampaign(true);if(a==='wizard-confirm')return confirmModal('Inicijuoti demonstracinį siuntimą?','Bus sukurtas Mailchimp inicijavimo pavyzdys ir įrašas žurnale. Tikri el. laiškai nebus siunčiami.',()=>saveCampaign(false),()=>renderWizard());if(a==='sync-rivile')return runSync('rivile');if(a==='sync-mail')return runSync('mail');if(a==='sync-all')return runSync();if(a==='reset')return confirmModal('Atkurti pavyzdinius duomenis?','Jūsų šioje naršyklėje atlikti pakeitimai bus pakeisti pradiniais pavyzdiniais duomenimis.',()=>{db=seed();persist();state.selected.clear();render();toast('Pavyzdiniai duomenys atkurti.');});}
document.addEventListener('click',e=>{let t=e.target.closest('[data-action],[data-nav],[data-open],[data-select],[data-sort],[data-client-open],[data-contact-open],[data-record-tab],[data-add-contact],[data-segment-edit],[data-segment-view],[data-segment-send],[data-template],[data-preview-template],[data-campaign-open]');if(!t)return;if(t.dataset.action)return action(t.dataset.action);if(t.dataset.nav)return nav(t.dataset.nav);if(t.dataset.open)return openRecord(t.dataset.open);if(t.dataset.select){let id=t.dataset.select;t.checked?state.selected.add(id):state.selected.delete(id);return updateTable();}if(t.dataset.sort){state.asc=state.sort===t.dataset.sort?!state.asc:true;state.sort=t.dataset.sort;return render();}if(t.dataset.clientOpen)return openRecord(t.dataset.clientOpen,'clients');if(t.dataset.contactOpen)return openRecord(t.dataset.contactOpen,'contacts');if(t.dataset.recordTab){let c=drawerContext;return openRecord(c.id,c.type,t.dataset.recordTab);}if(t.dataset.addContact){let id=t.dataset.addContact;openRecord(null,'contacts');document.getElementById('f-clientId').value=id;return;}if(t.dataset.segmentEdit)return openSegment(t.dataset.segmentEdit);if(t.dataset.segmentView)return viewSegment(t.dataset.segmentView);if(t.dataset.segmentSend)return startWizard(t.dataset.segmentSend);if(t.dataset.template){captureWizard();wizard.template=t.dataset.template;return renderWizard();}if(t.dataset.previewTemplate)return drawer('Šablono peržiūra','Mailchimp · demonstracinis šablonas',emailPreview(t.dataset.previewTemplate),button('Uždaryti','close'),true);if(t.dataset.campaignOpen)return viewCampaign(t.dataset.campaignOpen);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeOverlay();if(e.key==='Enter'&&e.target.id==='globalSearch'){state.page='clients';state.search=e.target.value;state.view='all';state.city='';state.sector='';state.pageIndex=0;render();if(!filteredRecords().length){state.page='contacts';render();}document.getElementById('recordSearch')?.focus();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]')){e.preventDefault();e.target.click();}if(e.key==='Tab'&&document.querySelector('#overlay [role=dialog]')){let d=document.querySelector('#overlay [role=dialog]'),els=[...d.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled&&x.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||!d.contains(document.activeElement))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||!d.contains(document.activeElement))){e.preventDefault();first?.focus();}}});
render();
